{"command": "python3 -c '
import re

# Fix libs/libc/signal/sig_wait.c
file_path = "/testbed/libs/libc/signal/sig_wait.c"
with open(file_path, "r") as f:
    content = f.read()

new_sigwait_body = r"""
{
  struct siginfo info;
  int signo;

  /* sigtimedwait returns the signal number that was caught */

  signo = sigtimedwait(set, &info, NULL);
  if (signo < 0)
    {
      return ERROR;
    }

  /* Return success with the signal number that was caught */

  if (sig)
    {
      *sig = signo;
    }

  return OK;
}
"""
content = re.sub(r"int\s*sigwait\s*\(.*?\)\s*\{.*\}",
                 "int sigwait(FAR const sigset_t *set, FAR int *sig)\n" + new_sigwait_body,
                 content, flags=re.S)

with open(file_path, "w") as f:
    f.write(content)


# Fix sched/signal/sig_timedwait.c
file_path = "/testbed/sched/signal/sig_timedwait.c"
with open(file_path, "r") as f:
    content = f.read()

# Replace bitwise operations with macros
content = content.replace("pendingset = tcb->sigpending;",
                          "nxsig_pendingset(tcb, &pendingset);")
content = content.replace("intersect = pendingset & *set;",
                          "SIGSET_AND(&intersect, &pendingset, set);")
content = content.replace("if (intersect != 0)",
                          "if (!SIGSET_ISNULL(&intersect))")

# Fix the loop for finding the signal
content = re.sub(r"sigmask = SIGNO2SET\(signo\);\s*if \(\(intersect & sigmask\) != 0\)",
                 "if (SIGSET_ISMEMBER(&intersect, signo))",
                 content)

# Replace variables type
content = content.replace("sigset_t pendingset;", "sigset_t pendingset;\n  sigset_t intersect;")
content = content.replace("sigset_t intersect;", "")
content = content.replace("sigset_t sigmask;", "")

with open(file_path, "w") as f:
    f.write(content)
'"}

