{"command": "python3 -c '
import re

file_path = "/testbed/sched/signal/sig_pending.c"

with open(file_path, "r") as f:
    content = f.read()

# Replace nxsig_pendingset
content = re.sub(r"sigset_t nxsig_pendingset\(FAR struct tcb_s \*stcb\)\s*\{[^}]*\}",
                 "void nxsig_pendingset(FAR struct tcb_s *stcb, FAR sigset_t *set)\n{\n  SIGSET_COPY(set, &stcb->sigpending);\n}",
                 content, flags=re.S)

# Replace nxsig_unblock_pendingsignal
new_unblock_logic = r"""
{
  FAR struct tcb_s *rtcb = this_task();
  sigset_t unblocked;

  /* This logic is probably called from an interrupt handler, but signals are
   * also probably disabled.
   */

  /* Dispatch any pending signals that are not blocked */

  unblocked.s[0] = rtcb->sigpending.s[0] & ~rtcb->sigprocmask.s[0];
  unblocked.s[1] = rtcb->sigpending.s[1] & ~rtcb->sigprocmask.s[1];

  if (!sigset_isnull(&unblocked))
    {
      nxsig_dispatch(rtcb);
    }
}
"""
content = re.sub(r"void nxsig_unblock_pendingsignal\(void\)\s*\{.*\}",
                 "void nxsig_unblock_pendingsignal(void)\n" + new_unblock_logic,
                 content, flags=re.S)

# Fix sigpending
new_sigpending = r"""
{
  FAR struct tcb_s *rtcb = this_task();
  int ret = OK;

  if (set)
    {
      nxsig_pendingset(rtcb, set);
    }
  else
    {
      ret = -EINVAL;
    }

  return ret;
}
"""

content = re.sub(r"int sigpending\(FAR sigset_t \*set\)\s*\{.*\}",
                 "int sigpending(FAR sigset_t *set)\n" + new_sigpending,
                 content, flags=re.S)

with open(file_path, "w") as f:
    f.write(content)
'"}

