{"command": "python3 -c '
import re

file_path = "/testbed/sched/signal/sig_procmask.c"
with open(file_path, "r") as f:
    content = f.read()

# Replace the body of nxsig_procmask
new_body = r"""
{
  FAR struct tcb_s *rtcb = this_task();
  irqstate_t flags;
  int ret = OK;

  flags = enter_critical_section();

  if (oset)
    {
      SIGSET_COPY(oset, &rtcb->sigprocmask);
    }

  if (set)
    {
      sigset_t newmask;

      SIGSET_COPY(&newmask, &rtcb->sigprocmask);

      switch (how)
        {
        case SIG_BLOCK:
          SIGSET_OR(&newmask, &newmask, set);
          break;

        case SIG_UNBLOCK:
          {
            sigset_t temp;
            temp.s[0] = ~set->s[0];
            temp.s[1] = ~set->s[1];
            SIGSET_AND(&newmask, &newmask, &temp);
          }
          break;

        case SIG_SETMASK:
          SIGSET_COPY(&newmask, set);
          break;

        default:
          ret = -EINVAL;
          break;
        }

      if (ret == OK)
        {
          SIGSET_DEL(&newmask, SIGKILL);
          SIGSET_DEL(&newmask, SIGSTOP);

          SIGSET_COPY(&rtcb->sigprocmask, &newmask);

          nxsig_unblock_pendingsignal();
        }
    }

  leave_critical_section(flags);
  return ret;
}
"""
content = re.sub(r"int nxsig_procmask\(int how, FAR const sigset_t \*set, FAR sigset_t \*oset\)\s*\{.*\}",
                 "int nxsig_procmask(int how, FAR const sigset_t *set, FAR sigset_t *oset)\n" + new_body,
                 content, flags=re.S)

# Also fix the wrapper sigprocmask if it exists in the file
content = re.sub(r"int sigprocmask\(int how, FAR const sigset_t \*set, FAR sigset_t \*oset\)\s*\{",
                 "int sigprocmask(int how, FAR const sigset_t *set, FAR sigset_t *oset)\n{\n  return nxsig_procmask(how, set, oset);\n}\n\n#ifdef CONFIG_BUILD_KERNEL",
                 content, flags=re.S)


with open(file_path, "w") as f:
    f.write(content)
'"}

